}

static int low[MAXV], num[MAXV], cnt;

static int upCycle[MAXV];    /* comprimento total do caminho de subida até a raiz da árvore de cacto */
static int cycLen[MAXV];

static int dfs(int v, int pe) {
    num[v]=low[v]=++cnt;
    parEdge[v]=pe;
    up[v]=0; bestExit[v]=INF; bestTour[v]=INF; bestany[v]=INF;
    for (int e=head[v]; e!=-1; e=ed[e].next) {
        if ((e^1)==pe) continue;
